// Conceptualizing the difference in a distributed cache access
public interface DataStore {
    // Strong: Blocks until all replicas acknowledge
    void putStrong(String key, String value) throws InterruptedException;

    // Eventual: Returns immediately, propagates in background
    void putEventual(String key, String value);
}

// Usage in a high-throughput microservice
public void updateProfile(String userId, String data) {
    // If using eventual consistency, we must handle stale reads
    store.putEventual(userId, data);
    log.info("Update accepted; replication will occur asynchronously.");
}
